mapper.delete:
delete from user_follow
where follower_id = #{followerId}
  and followee_id = #{followeeId}

mapper.select:
select exists(
    select 1 from user_follow
    where follower_id = #{followerId} and followee_id = #{followeeId}
)

select f.followee_id
from user_follow f
inner join sys_user u on u.user_id = f.followee_id and u.del_flag = 0
where f.follower_id = #{followerId}
order by f.created_at desc, f.followee_id desc
limit #{offset}, #{pageSize}

select f.follower_id
from user_follow f
inner join sys_user u on u.user_id = f.follower_id and u.del_flag = 0
where f.followee_id = #{followeeId}
order by f.created_at desc, f.follower_id desc
limit #{offset}, #{pageSize}

select f.follower_id
from user_follow f
inner join sys_user u on u.user_id = f.follower_id
where f.followee_id = #{followeeId}
  and f.follower_id > #{cursorUserId}
  and f.created_at <= #{occurredAt}
  and u.del_flag = 0
  and u.status = 0
order by f.follower_id asc
limit #{limit}
